import React,{useCallback,useEffect,useMemo,useRef,useState} from 'react';
import {Link,Navigate,Route,Routes,useLocation,useNavigate,useParams} from 'react-router-dom';
import {Activity,AirVent,ArrowDownToLine,ArrowLeft,ArrowRight, Bell,Building2,Check,ChevronDown,ChevronRight, CircleAlert, CircleHelp, Cloud, Cpu, Download, FileUp, Grid2X2, History, House, Info, KeyRound, Leaf, LoaderCircle, LogOut, Menu, Radio, RefreshCw, Plus, Search, Send, Settings, ShieldCheck, Thermometer, Trash2, UserRound, Users, Wifi, WifiOff, X} from 'lucide-react';
import {api,live,session} from './services';
import NodeListControls,{filterNodes,NodePages} from './NodeListControls';
import {canAdmin,canAnalyze,formatDate,isNewer,MATRIX,number,ROLE_LABEL,SEVERITY,VALIDITY} from './domain';

const TelegramPage=React.lazy(()=>import('./TelegramPage.jsx'));
const HistoryPage=React.lazy(()=>import('./HistoryPage.jsx'));
const PenpotLogin=React.lazy(()=>import('./PenpotLogin.jsx'));
const PenpotLocations=React.lazy(()=>import('./PenpotLocations.jsx'));
const PenpotUsers=React.lazy(()=>import('./PenpotUsers.jsx'));
const LocationsAdmin=React.lazy(()=>import('./LocationsAdmin.jsx'));
const NodeInventory=React.lazy(()=>import('./NodeInventory.jsx'));
const CascadeSelect=React.lazy(()=>import('./CascadeSelect.jsx'));
const Line=React.lazy(async()=>{const [{Line},{Chart,CategoryScale,LinearScale,PointElement,LineElement,Filler,Tooltip,Legend}]=await Promise.all([import('react-chartjs-2'),import('chart.js')]);Chart.register(CategoryScale,LinearScale,PointElement,LineElement,Filler,Tooltip,Legend);return {default:Line}});

const navItems=[
  {to:'/dashboard',label:'Inicio',icon:Grid2X2}, {to:'/historico',label:'Histórico',icon:Activity,roles:['ADMIN','ANALISTA']},
  {to:'/alertas',label:'Alertas',icon:Bell,roles:['ADMIN','ANALISTA']}, {to:'/telegram',label:'Telegram',icon:Send,roles:['ADMIN','ANALISTA','VIEWER']},
  {to:'/nodos',label:'Nodos',icon:Cpu,roles:['ADMIN']}, {to:'/espacios',label:'Espacios',icon:Building2,roles:['ADMIN']}, {to:'/usuarios',label:'Usuarios',icon:Users,roles:['ADMIN']}
];
function useSession(){const [,revise]=useState(0);useEffect(()=>session.subscribe(()=>revise(n=>n+1)),[]);return {user:session.user};}
function useLoad(loader,deps=[]){const [state,setState]=useState({data:null,loading:true,error:''});const reload=useCallback(async()=>{setState(s=>({...s,loading:true,error:''}));try{const data=await loader();setState({data,loading:false,error:''});return data}catch(e){setState({data:null,loading:false,error:e.message||'No fue posible cargar los datos'});return null}},deps);const setData=useCallback(d=>setState(s=>({...s,data:typeof d==='function'?d(s.data):d})),[]);useEffect(()=>{let active=true;(async()=>{try{const data=await loader();if(active)setState({data,loading:false,error:''})}catch(e){if(active)setState({data:null,loading:false,error:e.message||'No fue posible cargar los datos'})}})();return()=>{active=false}},deps);return {...state,reload,setData};}
function App(){const {user}=useSession();const loc=useLocation();const [restoring,setRestoring]=useState(true);
  useEffect(()=>{let alive=true;(async()=>{try{let current;try{current=await api.authSession()}catch(error){if(error.status!==401)throw error;await api.renew();current=await api.authSession()}if(alive)session.set(current)}catch(error){if(alive&&(error.status===401||error.status===403))session.set(null)}finally{if(alive)setRestoring(false)}})();return()=>{alive=false}},[]);
  const signOut=async()=>{try{await api.logout()}catch{}session.set(null)};
  if(restoring)return <div className="boot"><LoaderCircle className="spin"/> Comprobando sesión…</div>;
  return <React.Suspense fallback={<div className="boot"><LoaderCircle className="spin"/> Cargando sección…</div>}><Routes><Route path="/login" element={user?<Navigate to={loc.state?.from||'/dashboard'} replace/>:<PenpotLogin/>}/><Route path="/*" element={user?<Shell user={user} onSignOut={signOut}/>:<Navigate to="/login" replace state={{from:loc.pathname+loc.search}}/>}/></Routes></React.Suspense>
}
function Login(){const nav=useNavigate(),loc=useLocation();const [busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e){e.preventDefault();setBusy(true);setError('');try{await api.login({email:e.currentTarget.email.value,password:e.currentTarget.password.value});session.set(await api.authSession());nav(loc.state?.from||'/dashboard',{replace:true})}catch(err){setError(err.message)}finally{setBusy(false)}}
 return <main className="loginPage"><div className="loginBrand"><div className="brandMark"><Leaf size={26}/></div><div><b>AIRA</b><span>Monitoreo ambiental</span></div></div><section className="loginCard"><span className="eyebrow">PLATAFORMA INSTITUCIONAL</span><h1>Bienvenido</h1><p>Inicia sesión para consultar el estado ambiental de tus espacios.</p><form onSubmit={submit} className="stack"><label>Correo institucional<input name="email" type="email" autoComplete="username" placeholder="nombre@example.org" required/></label><label>Contraseña<input name="password" type="password" autoComplete="current-password" required/></label>{error&&<div className="notice error"><CircleAlert size={17}/>{error}</div>}<button className="primary wide" disabled={busy}>{busy?<LoaderCircle className="spin" size={17}/>:<KeyRound size={17}/>}Ingresar</button></form><div className="loginFoot"><ShieldCheck size={16}/> Acceso protegido por sesión institucional</div></section><div className="loginBottom">Plataforma AIRA</div></main>}
function Shell({user,onSignOut}){const loc=useLocation();const [mobile,setMobile]=useState(false);const items=navItems.filter(i=>!i.roles||i.roles.includes(user.rol));return <div className="appShell"><aside className={`rail ${mobile?'open':''}`}><Link to="/dashboard" className="logo"><Leaf size={21}/><span>AIRA</span></Link><div className="railLabel">AIRA</div><nav>{items.map(item=><NavItem key={item.to} item={item} active={loc.pathname===item.to||loc.pathname.startsWith(item.to+'/')||item.to==='/dashboard'&&['/sectores/','/edificios/','/pisos/','/salas/'].some(prefix=>loc.pathname.startsWith(prefix))} onClick={()=>setMobile(false)}/>)}</nav><div className="railBottom">{user.rol!=='GUEST'&&<Link to="/perfil" className={`avatarLink ${loc.pathname==='/perfil'?'active':''}`} title="Mi perfil">{(user.nombre||'U').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}</Link>}<button className="railLogout" onClick={onSignOut} title={user.rol==='GUEST'?'Salir de la vista de invitado':'Cerrar sesión'} aria-label={user.rol==='GUEST'?'Salir de la vista de invitado':'Cerrar sesión'}><LogOut size={18}/></button></div></aside>{mobile&&<button className="scrim" onClick={()=>setMobile(false)} aria-label="Cerrar menú"/>}<section className="mainColumn"><header className="topbar"><button className="mobileMenu iconBtn" onClick={()=>setMobile(true)} aria-label="Abrir menú"><Menu/></button><div className="crumb"><span>AIRA</span><ChevronRight size={14}/><span>Monitoreo de espacios</span></div><div className="topActions"><LiveIndicator/><div className="userChip"><span className="miniAvatar">{(user.nombre||'U')[0]}</span><span>{user.nombre}</span><span className="roleSmall">{ROLE_LABEL[user.rol]}</span><button className="iconBtn logout" title="Cerrar sesión" onClick={onSignOut}><LogOut size={17}/></button></div></div></header><main className="content"><React.Suspense fallback={<Loading/>}><Routes><Route path="/" element={<Navigate to="/dashboard" replace/>}/><Route path="/dashboard" element={<Dashboard user={user}/>}/><Route path="/sectores/:sectorId" element={<Protected user={user} roles={['ADMIN','ANALISTA','VIEWER','GUEST']}><PenpotLocations kind="sector"/></Protected>}/><Route path="/edificios/:edificioId" element={<Protected user={user} roles={['ADMIN','ANALISTA','VIEWER','GUEST']}><PenpotLocations kind="building"/></Protected>}/><Route path="/pisos/:pisoId" element={<Protected user={user} roles={['ADMIN','ANALISTA','VIEWER','GUEST']}><PenpotLocations kind="floor"/></Protected>}/><Route path="/salas/:salaId" element={<Protected user={user} roles={['ADMIN','ANALISTA','VIEWER','GUEST']}><RoomPage user={user}/></Protected>}/><Route path="/historico" element={<Protected user={user} roles={['ADMIN','ANALISTA']}><HistoryPage Chart={TelemetryChart} Table={TelemetryTable}/></Protected>}/><Route path="/alertas" element={<Protected user={user} roles={['ADMIN','ANALISTA']}><AlertsPage/></Protected>}/><Route path="/nodos" element={<Protected user={user} roles={['ADMIN']}><NodesPage/></Protected>}/><Route path="/nodos/administrar" element={<Protected user={user} roles={['ADMIN']}><NodeInventory/></Protected>}/><Route path="/espacios" element={<Protected user={user} roles={['ADMIN']}><LocationsAdmin/></Protected>}/><Route path="/usuarios" element={<Protected user={user} roles={['ADMIN']}><PenpotUsers currentUserId={user.id}/></Protected>}/><Route path="/telegram" element={<Protected user={user} roles={["ADMIN","ANALISTA","VIEWER"]}><TelegramPage user={user}/></Protected>}/><Route path="/perfil" element={<Protected user={user} roles={["ADMIN","ANALISTA","VIEWER"]}><ProfilePage user={user}/></Protected>}/><Route path="*" element={<NotFound/>}/></Routes></React.Suspense></main><footer className="footer"><span>AIRA / Monitoreo ambiental universitario</span><span>Datos con hora verificable · Zona horaria local</span></footer></section></div>}
function NavItem({item,active,onClick}){const Icon=item.icon;return <Link to={item.to} onClick={onClick} className={`navItem ${active?'active':''}`}><Icon size={21} strokeWidth={1.8}/><span>{item.label}</span></Link>}
function Protected({user,roles,children}){return roles.includes(user.rol)?children:<Navigate to="/dashboard" replace/>}
function PageHeading({kicker,title,description,action}){return <div className="pageHeading"><div><span className="eyebrow">{kicker}</span><h1>{title}</h1>{description&&<p>{description}</p>}</div>{action}</div>}
function Loading({label='Cargando información…'}){return <div className="loading"><LoaderCircle className="spin" size={21}/>{label}</div>}
/**
 * Nombre   : LiveIndicator
 * Razón    : Muestra el estado actual del canal WebSocket que alimenta las vistas en vivo.
 * Entradas : large - indica si se usa el tamaño destacado del encabezado de una página.
 * Salida   : Indicador accesible con el estado de conexión actual.
 * Efectos  : Se suscribe al estado del socket mientras el componente está montado.
 */
function LiveIndicator({large=false}){const [status,setStatus]=useState(live.status);useEffect(()=>live.subscribeStatus(setStatus),[]);const labels={connected:'En tiempo real',connecting:'Conectando…',reconnecting:'Reconectando…',disconnected:'Sin conexión'};return <span className={`livePill live-${status}${large?' large':''}`} role="status" aria-live="polite"><i/>{labels[status]||labels.disconnected}</span>}
function Empty({title='Aún no hay datos',text='Las lecturas aparecerán cuando se reciba una ventana verificable.',icon:Icon=Info}){return <div className="empty"><Icon size={23}/><b>{title}</b><span>{text}</span></div>}
function Problem({error,onRetry}){return <div className="notice error"><CircleAlert size={17}/><span>{error}</span>{onRetry&&<button className="textButton" onClick={onRetry}>Reintentar</button>}</div>}
function Metric({label,value,unit,accent,detail}){return <article className={`metric ${accent||''}`}><span>{label}</span><strong>{value==null?'—':number(value,1)}</strong><small>{unit}{detail?` · ${detail}`:''}</small></article>}
function StateBadge({score,state}){if(!state||state==='dato_insuficiente'||score==null)return <span className="badge muted">Dato insuficiente</span>;const cls=['good','caution','poor','bad','critical'][score]||'muted';return <span className={`badge ${cls}`}>{score} · {SEVERITY[score]}</span>}
function CardState({state,room,href}){const s=state||{};return <Link to={href||`/salas/${room?.id||s.salaId}`} className="roomCard"><div className="roomTop"><span className="roomType">{s.pisoNombre||'Espacio monitorizado'}</span>{s.nodoEstado==='conectado'?<span className="connected"><Wifi size={14}/> Conectado</span>:<span className="disconnected"><WifiOff size={14}/> Desconectado</span>}</div><h3>{s.salaNombre||room?.nombre||room?.id||'Sala'}</h3><StateBadge score={s.icgScore} state={s.icgEstado}/><div className="roomMetrics"><span>CO₂ <b>{number(s.co2,0)}</b></span><span>PM₂.₅ <b>{number(s.pm25,0)}</b></span><span>Temp. <b>{number(s.temperatura,1)}°</b></span></div><div className="roomFoot"><span>{formatDate(s.ventanaTimestamp,{hour:'2-digit',minute:'2-digit'})}</span><ChevronRight size={16}/></div></Link>}
function useCampus(){return useLoad(()=>api.campus(),[])}
function Dashboard({user}){const {data,loading,error,reload,setData:setCampus}=useCampus();const [alerts,setAlerts]=useState([]);useEffect(()=>{if(canAnalyze(user))api.alerts({estado:'activa',limite:100}).then(setAlerts).catch(()=>setAlerts([]))},[user]);useEffect(()=>live.subscribe(event=>{if(event.tipo==='ventana'&&event.salaId){if(user.rol==='GUEST')api.campus().then(setCampus).catch(()=>{});else api.state(event.salaId).then(fresh=>setCampus(current=>current&&({...current,states:current.states.map(state=>state.salaId===fresh.salaId?fresh:state)}))).catch(()=>{})}if(event.tipo==='alerta'&&canAnalyze(user))api.alerts({estado:'activa',limite:100}).then(setAlerts).catch(()=>{})}),[setCampus,user]);const counts=useMemo(()=>{const states=data?.states||[];return {total:states.length,good:states.filter(s=>s.icgEstado==='completo'&&s.icgScore===0).length,attention:states.filter(s=>s.icgScore>=3&&s.icgEstado==='completo').length,connected:states.filter(s=>s.nodoEstado==='conectado').length,partial:states.filter(s=>s.icgEstado==='parcial').length,insufficient:states.filter(s=>s.icgEstado==='dato_insuficiente'||!s.icgEstado).length}},[data]);const activeAlerts=alerts.filter(a=>a.estado==='activa');return <><PageHeading kicker="MONITOREO AMBIENTAL / 02" title="Una mirada al campus" description="Explora tus espacios y detecta dónde actuar. La tarjeta actual conserva la ventana verificable más reciente." action={<LiveIndicator large/>}/>{loading?<Loading/>:error?<Problem error={error} onRetry={reload}/>:<>{activeAlerts.length>0&&<div className="alertBanner"><Bell size={19}/><div><b>{activeAlerts.length} alertas activas requieren atención</b><span>{activeAlerts.slice(0,2).map(a=>`${a.variable||'Variable'} · nivel ${a.nivel}`).join('  /  ')}</span></div>{canAnalyze(user)&&<Link to="/alertas" className="secondary compact">Ver alertas →</Link>}</div>}<div className="statGrid"><StatCard title="Salas monitorizadas" value={counts.total} note={`En ${data.sectors.length} sectores permitidos`}/><StatCard title="Condición óptima" value={counts.good} note={counts.total?`${Math.round(100*counts.good/counts.total)} % de salas con datos completos`:'Sin lecturas'} tone="green"/><StatCard title="Requieren atención" value={counts.attention} note="Nivel 3 o 4 con dato completo" tone="red"/><StatCard title="Nodos conectados" value={`${counts.connected} / ${counts.total}`} note={`${counts.total-counts.connected} sin conexión · revisar última ventana`} tone="teal"/></div><div className="sectionTitle"><h2>Explora por sector</h2><span>Espacios dentro de tu ámbito autorizado</span></div><div className="sectorGrid">{data.sectors.map(sector=>{const buildings=data.buildings.filter(b=>b.sectorId===sector.id);const buildingIds=buildings.map(b=>b.id);const states=data.states.filter(s=>buildingIds.includes(s.edificioId));const alertCount=states.filter(s=>s.icgEstado==='completo'&&s.icgScore>=2).length;return <Link key={sector.id} to={`/sectores/${sector.id}`} className="sectorCard"><div className="sectorHead"><span className={`badge ${alertCount?'caution':'good'}`}>{alertCount?'Atención':'Operativo'}</span><Grid2X2 size={20}/></div><h3>{sector.nombre}</h3><p>{states.length} salas · {buildings.length} edificios</p><div className="sectorDivider"/><div className="sectorFoot"><span>{states.filter(s=>s.icgEstado==='completo'&&s.icgScore===0).length} óptimas</span><span>{alertCount?`${alertCount} requieren atención`:'Sin condiciones de atención'}</span></div><div className="progress"><i style={{width:`${states.length?100*states.filter(s=>s.icgEstado==='completo'&&s.icgScore===0).length/states.length:0}%`}}/></div></Link>})}{!data.sectors.length&&<Empty title="No hay sectores asignados" text="Solicita acceso a un administrador para ver los espacios."/>}</div><div className="dashboardLower"><section className="panel"><div className="panelHead"><h2>Últimos avisos operacionales</h2>{canAnalyze(user)&&<Link to="/alertas" className="quietLink">Ver historial →</Link>}</div>{activeAlerts.slice(0,4).map(alert=><Link className="alertRow" key={alert.id} to={canAnalyze(user)?'/alertas':`/salas/${alert.salaId}`}><time>{formatDate(alert.ventanaConfirmacion||alert.createdAt,{hour:'2-digit',minute:'2-digit'})}</time><b>{data.rooms.find(room=>room.id===alert.salaId)?.nombre||alert.salaId} · {alert.variable}</b><span className={`badge ${alert.nivel===4?'critical':'bad'}`}>Nivel {alert.nivel}</span></Link>)}{!activeAlerts.length&&<Empty title="Sin avisos operacionales activos" text="Las alertas confirmadas aparecerán aquí cuando una condición requiera atención." icon={Bell}/>}</section><section className="panel qualityPanel"><h2>Calidad de la información</h2><p>{counts.total-counts.partial-counts.insufficient} completas · {counts.partial} parciales · {counts.insufficient} insuficientes</p><div className="qualityBadges"><span className="badge muted">Parcial</span><span className="badge muted">Dato insuficiente</span></div><small>Las retransmisiones se integran al histórico. La lectura actual conserva la ventana más reciente.</small></section></div></>}</>}
function StatCard({title,value,note,tone=''}){return <article className={`statCard ${tone}`}><span>{title}</span><strong>{value}</strong><small>{note}</small></article>}
function RoomPage({user}){const {salaId}=useParams();const room=useLoad(()=>api.state(salaId,{incluirComplementos:false}),[salaId]);const [history,setHistory]=useState([]);const [oms,setOms]=useState(null);const [refreshing,setRefreshing]=useState(false);const [complementError,setComplementError]=useState('');useEffect(()=>{if(room.data?.salaId!==salaId)return;let active=true;setComplementError('');api.stateComplements(salaId).then(complements=>{if(active)room.setData(current=>current?({...current,...complements}):current)}).catch(error=>{if(active)setComplementError(error.message||'No fue posible cargar los datos complementarios')});return()=>{active=false}},[salaId,room.data?.salaId]);useEffect(()=>{if(!canAnalyze(user))return;api.telemetry(salaId,{limite:120}).then(rows=>setHistory(rows.slice().reverse())).catch(()=>setHistory([]));},[salaId,user]);useEffect(()=>{if(canAnalyze(user)&&room.data?.particulas24hOMS)setOms(room.data.particulas24hOMS)},[room.data,user]);useEffect(()=>{const unsub=live.subscribe(async event=>{if(event.salaId!==salaId||event.tipo!=='ventana')return;setRefreshing(true);const current=room.data?.ventanaTimestamp;if(!isNewer(event.timestamp,current)){if(canAnalyze(user))api.telemetry(salaId,{limite:120}).then(rows=>setHistory(rows.slice().reverse())).catch(()=>{});setRefreshing(false);return}try{const fresh=await api.state(salaId,{incluirComplementos:false});if(isNewer(fresh.ventanaTimestamp,current))room.setData(value=>({...value,...fresh}));api.stateComplements(salaId).then(complements=>room.setData(value=>value?({...value,...complements}):value)).catch(error=>setComplementError(error.message||'No fue posible cargar los datos complementarios'));if(canAnalyze(user))api.telemetry(salaId,{limite:120}).then(rows=>setHistory(rows.slice().reverse())).catch(()=>{})}finally{setRefreshing(false)}});return unsub},[salaId,room.data?.ventanaTimestamp,user]);if(room.loading)return <Loading/>;if(room.error)return <Problem error={room.error} onRetry={room.reload}/>;const s=room.data||{};const analyzer=canAnalyze(user);return <><PageHeading kicker="MONITOREO AMBIENTAL / 06" title={s.salaNombre||s.salaId||'Sala'} description={<span><Link to={`/sectores/${s.sectorId}`}>{s.sectorNombre}</Link>　/　<Link to={`/edificios/${s.edificioId}`}>{s.edificioNombre}</Link>　/　<Link to={`/pisos/${s.pisoId}`}>{s.pisoNombre}</Link>　/　{s.nodoId||'Sin nodo'}</span>} action={<Link to={`/pisos/${s.pisoId}`} className="secondary"><ArrowLeft size={15}/> Ver salas</Link>}/>{complementError&&<Problem error={complementError}/>}<div className="windowStrip"><span className={s.nodoEstado==='conectado'?'connected':'disconnected'}>{s.nodoEstado==='conectado'?<Wifi size={14}/>:<WifiOff size={14}/>} Nodo {s.nodoEstado||'sin estado'}</span><span>Ventana actual: {formatDate(s.ventanaTimestamp,{dateStyle:'medium',timeStyle:'short'})} · Hora verificable</span>{refreshing&&<LoaderCircle className="spin" size={15}/>}</div><div className="indexPanel">{[['ICG','Calidad global','icgScore','icgEstado'],['ICAI','Calidad del aire','icaiScore','icaiEstado'],['ICT','Confort térmico','ictScore','ictEstado']].map(([name,label,scoreKey,stateKey])=><div className="indexCell" key={name}><span>{name} · {label}</span><div><b className={`indexScore score${s[scoreKey]??'na'}`}>{s[stateKey]==='dato_insuficiente'||s[scoreKey]==null?'—':s[scoreKey]}</b><StateBadge score={s[scoreKey]} state={s[stateKey]}/></div><small>{VALIDITY[s[stateKey]]||'Sin lectura'} · Reglas {s.versionReglas||'—'}</small></div>)}</div><div className="metricGrid"><Metric label="CO₂" value={s.co2} unit="ppm" accent={s.causasICAI?.includes('CO2')?'red':''} detail="Ventana 5 min"/><Metric label="PM₂.₅" value={s.pm25} unit="µg/m³" detail="Ventana 5 min"/><Metric label="PM₁₀" value={s.pm10} unit="µg/m³" detail="Ventana 5 min"/><Metric label="Temperatura" value={s.temperatura} unit="°C" detail="Ventana 5 min"/><Metric label="Humedad" value={s.humedad} unit="%" detail="Ventana 5 min"/></div><div className="diagnosticGrid"><section className="panel matrixPanel"><h2>Diagnóstico combinado</h2><p>D = ({s.icaiScore??'—'}, {s.ictScore??'—'}) · Código {s.celdaMatriz||'—'}</p><Matrix cell={s.celdaMatriz}/><small>El cliente muestra la clasificación calculada en el nodo, sin volver a aplicar las reglas ambientales.</small></section><section className={`recommendation ${s.icgScore>=3?'recommendBad':''}`}><span>{s.icgScore>=3?'Aviso operacional':'Recomendación operacional'}</span><h2>{(s.recomendaciones||[])[0]||'Sin recomendación disponible'}</h2><p>Causas de aire: {(s.causasICAI||[]).join(' + ')||'—'}<br/>Causas térmicas: {(s.causasICT||[]).join(' + ')||'—'}</p>{s.alertasActivas?.length>0&&<div className="persistence"><b>Persistencia confirmada</b><span>{s.alertasActivas.map(a=>a.variable).join(', ')} · avise al encargado.</span></div>}</section></div><div className="roomLower">{analyzer?<><section className="panel chartPanel"><div className="panelHead"><div><h2>Evolución ambiental</h2><span>Ventanas verificables de 5 minutos · incluye retransmisiones fechadas</span></div><Link to={`/historico?sala=${encodeURIComponent(salaId)}`} className="secondary">Ver histórico →</Link></div><TelemetryChart rows={history}/></section><OmsCard value={oms||s.particulas24hOMS}/></>:<section className="panel viewerInfo"><Info/><div><b>Vista de estado actual</b><span>El análisis histórico y la comparación informativa de 24 horas requieren rol ADMIN o ANALISTA.</span></div></section>}</div><section className="panel provenance"><h2>Datos verificables, decisiones con contexto</h2><p>Completitud: {VALIDITY[s.icgEstado]||'dato insuficiente'} · Reglas: {s.versionReglas||'—'} · Ventana: {formatDate(s.ventanaTimestamp,{dateStyle:'medium',timeStyle:'medium'})} · Nodo: {s.nodoId||'sin nodo'}</p><small>Las ventanas atrasadas se agregan al histórico sin reemplazar el estado actual. Los paquetes sin hora verificable quedan pendientes de validación.</small></section></>}
